result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    days_to_first_transaction=DATEDIFF("seconds", join_date, MIN(transactions_made.date_time)) / 86400
)

result = Dealership.CALCULATE(
    number_of_sales=COUNT(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (LOWER(car.make) == LOWER("Toyota"))
        )
    ),
    total_revenue=SUM(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (LOWER(car.make) == LOWER("Toyota"))
        ).sale_price
    )
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            Sales.WHERE(HAS(payment) == 1).payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

result = Ewallet.CALCULATE(
    num_transactions=COUNT(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        )
    ),
    total_amount=SUM(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        ).amount
    )
)

user_session_durations = UserSessions.WHERE(
    (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
).CALCULATE(
    user_id=user_id,
    session_duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
).PARTITION(
    name="sessions_by_user", by=(user_id,)
).CALCULATE(
    user_id=user_id,
    total_duration=SUM(UserSessions.session_duration)
).ORDER_BY(total_duration.DESC())

users_without_notifications_in_first_year = Ewallet.Users.WHERE(
    HASNOT(
        notifications.WHERE(created_at < DATETIME(created_at, '+1 year'))
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
